-- Reference schema; Hibernate creates/updates these tables on startup.
CREATE TABLE IF NOT EXISTS app_users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(40), password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS turfs (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, location VARCHAR(255) NOT NULL, sport VARCHAR(80) NOT NULL, description TEXT, price_per_hour DECIMAL(10,2) NOT NULL, image_url VARCHAR(1000), status VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS bookings (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, turf_id BIGINT NOT NULL, booking_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, amount DECIMAL(10,2) NOT NULL, booking_status VARCHAR(20) NOT NULL, payment_status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL, INDEX idx_booking_slot (turf_id,booking_date,start_time,end_time), FOREIGN KEY(user_id) REFERENCES app_users(id), FOREIGN KEY(turf_id) REFERENCES turfs(id));
